var minOperations = function(nums) {
    const n = nums.length;
    let bp = -1;

    for (let i = 0; i < n; i++) {
        if (nums[i] > nums[(i + 1) % n]) {
            if (bp > -1) {
                bp = -2;
                break;
            }
            bp = i;
        }
    }

    if (bp === n - 1) return 0;
    if (bp !== -2) return Math.min(bp + 1, n - bp + 1);

    bp = -1;

    for (let i = 0; i < n; i++) {
        if (nums[i] < nums[(i + 1) % n]) {
            if (bp > -1) {
                bp = -2;
                break;
            }
            bp = i;
        }
    }

    if (bp === -2) return -1;

    return Math.min(bp + 1, n - bp - 1) + 1;
